import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

scale_min_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void scale_and_min_kernel(const float* input, float* output, float scale_factor, int batch_size, int channels, int height, int width) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_positions = batch_size * height * width;
    if (idx >= total_positions) return;

    int b = idx / (height * width);
    int hw = idx % (height * width);
    int h = hw / width;
    int w = hw % width;

    float min_val = INFINITY;
    for (int c = 0; c < channels; ++c) {
        int input_idx = ((b * channels + c) * height + h) * width + w;
        float val = input[input_idx] * scale_factor;
        min_val = fminf(min_val, val);
    }

    output[idx] = min_val;
}

torch::Tensor scale_and_min_cuda(torch::Tensor input, float scale_factor) {
    int batch_size = input.size(0);
    int channels = input.size(1);
    int height = input.size(2);
    int width = input.size(3);

    auto output = torch::empty({batch_size, 1, height, width}, input.options());

    int total_positions = batch_size * height * width;
    int block_size = 256;
    int grid_size = (total_positions + block_size - 1) / block_size;

    scale_and_min_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        scale_factor,
        batch_size,
        channels,
        height,
        width
    );

    return output;
}
"""

scale_min_cpp_source = "torch::Tensor scale_and_min_cuda(torch::Tensor input, float scale_factor);"

scale_min = load_inline(
    name="scale_min",
    cpp_sources=scale_min_cpp_source,
    cuda_sources=scale_min_source,
    functions=["scale_and_min_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scale_factor):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.scale_factor = scale_factor
        self.scale_and_min = scale_min

    def forward(self, x):
        x = self.conv(x)
        x = self.scale_and_min.scale_and_min_cuda(x, self.scale_factor)
        return x
